void Arithmetizer_arith_or(Arithmetizer* ar, uint32_t col_a, uint32_t col_b) {
    int8_t val_a = (*(int8_t*)yvec_get((&(*ar).coeff_buf), col_a));
    int8_t val_b = (*(int8_t*)yvec_get((&(*ar).coeff_buf), col_b));
    int8_t product = (val_a * val_b);
    int8_t result = ((val_a + val_b) - product);
    Vec_set_I8((&(*ar).coeff_buf), col_a, result);
    int8_t zero = 0;
    Vec_set_I8((&(*ar).coeff_buf), col_b, zero);
}

void Arithmetizer_arith_not(Arithmetizer* ar, uint32_t col) {
    int8_t val = (*(int8_t*)yvec_get((&(*ar).coeff_buf), col));
    int8_t complement = (1 - val);
    Vec_set_I8((&(*ar).coeff_buf), col, complement);
}

