typedef struct ConflictRecord ConflictRecord;
typedef struct LearnedClause LearnedClause;
typedef struct BcpEngine BcpEngine;

struct ConflictRecord {
    uint32_t clause_row;
    uint32_t conflict_var;
    uint32_t ballot_mask;
    uint32_t iteration;
};

struct LearnedClause {
    uint32_t lit_start;
    uint32_t lit_count;
    uint32_t backtrack_level;
};

struct BcpEngine {
    YVec assignments;
    uint32_t num_variables;
    uint32_t decision_level;
    YVec conflicts;
    uint32_t conflict_count;
    YVec learned;
    uint32_t learned_count;
    YVec prop_queue;
    uint32_t prop_head;
    uint32_t prop_tail;
    uint32_t iteration;
};

typedef enum {
    ClauseState_TAG_Satisfied,
    ClauseState_TAG_Unsatisfied,
    ClauseState_TAG_Unit,
    ClauseState_TAG_Unresolved
} ClauseState_Tag;

typedef struct {
    uint32_t _0;
} ClauseState_Unit_Data;

typedef struct {
    ClauseState_Tag tag;
    union {
        ClauseState_Unit_Data Unit;
    } data;
} ClauseState;

#define ClauseState_Satisfied ((ClauseState){ .tag = ClauseState_TAG_Satisfied })
#define ClauseState_Unsatisfied ((ClauseState){ .tag = ClauseState_TAG_Unsatisfied })
static inline ClauseState ClauseState_Unit(uint32_t _0) {
    ClauseState res;
    res.tag = ClauseState_TAG_Unit;
    res.data.Unit._0 = _0;
    return res;
}

#define ClauseState_Unresolved ((ClauseState){ .tag = ClauseState_TAG_Unresolved })
ConflictRecord Vec_get_ConflictRecord(const YVec* v, size_t i);
ClauseState Vec_get_ClauseState(const YVec* v, size_t i);
