void BcpEngine_threshold_evaluate(BcpEngine* bcp, const AccumulatorTile* acc, uint32_t num_clauses, uint32_t num_vars, YVec* out_states);
LearnedClause BcpEngine_cdcl_analyze(BcpEngine* bcp, const AccumulatorTile* acc, uint32_t conflict_clause, uint32_t num_vars);
bool BcpEngine_propagate(BcpEngine* bcp);
