SolverConfig SolverConfig_default(void);
int booledass_solve(unsigned num_vars, unsigned num_clauses, const int8_t* matrix_data);

static const int32_t TILE_M = 16;

static const int32_t TILE_N = 8;

static const int32_t TILE_K = 16;

static const int32_t SOLVER_WARP_SIZE = 32;

static const uint32_t FULL_MASK = 4294967295;

static const int32_t SAT_TRUE = 1;

static const int32_t SAT_FALSE = 0;

static const int32_t SAT_UNDEF = (-1);

static const uint64_t VRAM_BUDGET_BYTES = 268435456;

/* impl SolverConfig */
SolverConfig SolverConfig_default(void) {
    SolverConfig cfg = {0};
    cfg.max_iterations = 4096;
    cfg.vram_budget = VRAM_BUDGET_BYTES;
    cfg.enable_cdcl = true;
    cfg.enable_aig_prune = true;
    cfg.tile_m = TILE_M;
    cfg.tile_n = TILE_N;
    cfg.tile_k = TILE_K;
    return cfg;
}

/* Extern declaration for the real GPU BCP solver (in booledass_kernels.cu) */
extern int gpu_bcp_solve(const int8_t* host_matrix, uint32_t num_vars, uint32_t num_clauses);

int booledass_solve(unsigned num_vars, unsigned num_clauses, const int8_t* matrix_data) {
    printf("[booledass] GPU SAT intercept: %u vars, %u clauses\n", num_vars, num_clauses);

    if (num_clauses == 0 || num_vars == 0) {
        printf("[booledass] Trivial instance, returning UNDEF\n");
        return SAT_UNDEF;
    }

    /* Call the real CUDA BCP solver */
    int gpu_result = gpu_bcp_solve(matrix_data, num_vars, num_clauses);

    if (gpu_result == 1) {
        printf("[booledass] >>> GPU BCP: SATISFIABLE\n");
        return SAT_TRUE;
    } else if (gpu_result == 0) {
        printf("[booledass] >>> GPU BCP: UNSATISFIABLE (conflict)\n");
        return SAT_FALSE;
    } else {
        printf("[booledass] >>> GPU BCP: UNDETERMINED -> CPU CDCL fallback\n");
        return SAT_UNDEF;
    }
}

